async function handler(input) {
  const { client_id, client_secret } = input;
  const testOrderId = 'test_order_' + Date.now();

  const createRes = await fetch('https://sandbox.cashfree.com/pg/orders', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'x-api-version': '2023-08-01',
      'x-client-id': client_id,
      'x-client-secret': client_secret
    },
    body: JSON.stringify({
      order_id: testOrderId,
      order_amount: 1.00,
      order_currency: 'INR',
      customer_details: {
        customer_id: 'sandbox_test_user',
        customer_email: 'sandbox@cashfree.test',
        customer_phone: '9999999999'
      }
    })
  });

  const orderData = await createRes.json();
  if (!createRes.ok) {
    return { success: false, phase: 'ORDER_CREATION', error: orderData.message };
  }

  const getRes = await fetch(`https://sandbox.cashfree.com/pg/orders/${testOrderId}`, {
    method: 'GET',
    headers: {
      'x-api-version': '2023-08-01',
      'x-client-id': client_id,
      'x-client-secret': client_secret
    }
  });

  const statusData = await getRes.json();
  return {
    success: true,
    message: 'Cashfree Sandbox test passed!',
    test_order_id: testOrderId,
    order_status: statusData.order_status,
    payment_session_id: orderData.payment_session_id
  };
}
